package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A period of a sheet: a name unique on the sheet, and the from and to dates it covers, both inclusive. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed, yet claims dated in it can still change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    @Column(name = "closed_total", precision = 14, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total for the period, by person id, fixed when it was closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", precision = 14, scale = 2)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** Each person's carried figure for the period, by person id, fixed when it was closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", precision = 14, scale = 2)
    private Map<Long, BigDecimal> personCarried = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer cap) {
        this(sheetId, name, fromDate, toDate);
        this.cap = cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getPersonTotals() {
        return Map.copyOf(personTotals);
    }

    public Map<Long, BigDecimal> getPersonCarried() {
        return Map.copyOf(personCarried);
    }

    /** Close the period, fixing each person's due-total and carried figure for it and its own due-total, their sum. */
    public void close(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
        this.closed = true;
        this.softClosed = false;
        fix(totals, carried);
    }

    /** Soft-close the period, fixing its figures as a close does while its claims can still change. */
    public void softClose(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
        this.softClosed = true;
        fix(totals, carried);
    }

    private void fix(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
        this.personTotals.clear();
        this.personTotals.putAll(totals);
        this.personCarried.clear();
        this.personCarried.putAll(carried);
        this.closedTotal = totals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Fold one person's fixed due-total into another's, keeping the period's own (a merge of the two). */
    public void mergePersonTotal(Long fromId, Long intoId) {
        BigDecimal from = personTotals.remove(fromId);
        if (from != null) {
            personTotals.merge(intoId, from, BigDecimal::add);
        }
        BigDecimal carried = personCarried.remove(fromId);
        if (carried != null) {
            personCarried.merge(intoId, carried, BigDecimal::add);
        }
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
        this.personCarried.clear();
    }

    /** Whether the date falls in the period, both ends inclusive. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether the period shares a day with the dates from and to, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.function.Function;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the periods of each sheet: uniquely named, and no two overlapping; a closed period's claims are fixed. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, Audit audit, RollupService rollup,
            RoleService roles) {
        this.periods = periods;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
        this.roles = roles;
    }

    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId);
    }

    /**
     * Add a period, with a cap on the OPEN or PENDING claims each person may have in it (null for none); refused when
     * its name is taken, its dates are reversed, its cap is below 1, or it overlaps another period.
     */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
        // Lock the sheet so two periods added at once are checked against each other.
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        if (to.isBefore(from)) {
            throw new PeriodRefusedException("The period " + name + " ends before it starts");
        }
        if (cap != null && cap < 1) {
            throw new PeriodRefusedException("The period " + name + " cannot cap claims at " + cap);
        }
        if (periods.existsBySheetIdAndName(sheetId, name)) {
            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
        }
        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new PeriodRefusedException("The period " + name + " overlaps another period on sheet " + sheetId);
        }
        Period saved;
        try {
            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
                + (saved.getCap() == null ? "" : " cap=" + saved.getCap()));
        return saved;
    }

    /**
     * Generate one period per calendar month from the from-date's month to the to-date's month, each named yyyy-mm and
     * running from the first to the last day of its month; a month whose name is taken or whose days overlap a period
     * on the sheet is left out. Refused when the to-date is before the from-date. The periods made, in date order.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        if (to.isBefore(from)) {
            throw new PeriodRefusedException("The to-date " + to + " is before the from-date " + from);
        }
        List<Period> existing = new ArrayList<>(list(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
                continue;
            }
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            existing.add(saved);
            made.add(saved);
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
        }
        return made;
    }

    /**
     * Generate the twelve monthly periods of the fiscal year named FY{@code year}, from the first day of the sheet's
     * fiscal year start month in that year, as a generate over its dates would. The periods made, in date order.
     */
    @Transactional
    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
        YearMonth first = YearMonth.of(year, sheet.getFiscalStartMonth());
        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
    }

    /** The name (FYyyyy) of the fiscal year a date falls in on the sheet; by a January start when there is no such sheet. */
    public Function<LocalDate, String> fiscalYears(String sheetId) {
        int startMonth = sheets.findById(sheetId).map(Sheet::getFiscalStartMonth).orElse(1);
        return date -> Sheet.fiscalYearOf(date, startMonth);
    }

    /** Close a period, fixing every person's due-total and carried figure for it, and so its own, as they are now; refused when it is already closed or the user's role may not close; a soft-closed period's figures are fixed afresh. */
    @Transactional
    public Period close(String sheetId, String user, String name) {
        // Lock the sheet so no claim in the period changes while its total is fixed.
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
        if (!roles.may(sheetId, user, "close")) {
            throw new PeriodCloseForbiddenException(name, user);
        }
        if (period.isClosed()) {
            throw new PeriodClosedException(name);
        }
        return closeNow(sheetId, user, period, false);
    }

    /**
     * Soft-close a period, fixing every person's due-total and carried figure for it, and so its own, as they are now, while claims due by
     * a date in it can still change; refused when it is closed or soft-closed already or the user's role may not close.
     */
    @Transactional
    public Period softClose(String sheetId, String user, String name) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
        if (!roles.may(sheetId, user, "close")) {
            throw new PeriodCloseForbiddenException(name, user);
        }
        if (period.isClosed() || period.isSoftClosed()) {
            throw new PeriodClosedException(name);
        }
        period.softClose(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedInto(sheetId, list(sheetId), period));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString());
        return saved;
    }

    /**
     * Close, in order of their to-dates, every open period (neither closed nor soft-closed) whose to-date plus the
     * grace days is before the today, as a close by hand would, each recorded as closed automatically; none when the
     * grace days are off (null).
     */
    @Transactional
    public void autoClose(String sheetId, String user, LocalDate today, Integer graceDays) {
        if (graceDays == null) {
            return;
        }
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        list(sheetId).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeNow(sheetId, user, p, true));
    }

    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
        period.close(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedInto(sheetId, list(sheetId), period));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString() + (auto ? " auto=yes" : ""));
        return saved;
    }

    /**
     * Reopen a closed or soft-closed period, making its due-total and carried figures live again; refused unless the user's role may reopen
     * and it is closed or soft-closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
        if (!roles.may(sheetId, user, "reopen")) {
            throw new PeriodReopenForbiddenException(name, user);
        }
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new PeriodNotClosedException(name);
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    /** The name of the period the date falls in; empty when it is in none. */
    public Optional<String> nameOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.contains(date)).map(Period::getName).findFirst();
    }

    /** The period the date falls in; empty when it is in none. */
    public Optional<Period> on(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.contains(date)).findFirst();
    }

    /** Whether the date falls in a soft-closed period of the sheet. */
    public boolean softClosedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().anyMatch(p -> p.isSoftClosed() && p.contains(date));
    }

    /**
     * Refuse a change to a claim due by any of the dates when one falls in a closed period. The sheet is locked
     * until the caller's transaction ends, so a period cannot close while the change is made.
     */
    @Transactional
    public void requireOpen(String sheetId, LocalDate... dates) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        for (Period period : list(sheetId)) {
            for (LocalDate date : dates) {
                if (period.isClosed() && period.contains(date)) {
                    throw new PeriodClosedException(period.getName(), date);
                }
            }
        }
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Adds or updates a person per pasted line of name,grade,terms,contact, in order, each as the person form would (the
 * terms and the contact may be absent or blank). A line whose name matches a person on the sheet, by name or alias,
 * updates them: their grade is recorded from the sheet's today, and their terms and contact are set when the line
 * gives them. Every other line adds a person. Every line is checked first with the person form's rules, and a person
 * or a contact repeated within the paste is refused too. The whole is one change: if any line is refused, nothing is
 * imported.
 */
@Service
public class ImportPeopleService {

    private static final int MAX_NAME = 200;

    private static final int MAX_CONTACT = 200;

    private record Line(int number, String name, String grade, Integer terms, String contact) {
    }

    /** How many people an import added and how many it updated. */
    public record Result(int added, int updated) {
    }

    private final PersonService people;

    public ImportPeopleService(PersonService people) {
        this.people = people;
    }

    /** How many people were added and how many updated. */
    @Transactional
    public Result importPeople(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        String[] rows = text.split("\\r?\\n");
        for (int i = 0; i < rows.length; i++) {
            if (!rows[i].isBlank()) {
                lines.add(parse(i + 1, rows[i]));
            }
        }
        if (lines.isEmpty()) {
            throw new ImportPeopleException("Paste at least one line of name,grade,terms,contact");
        }
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        List<Person> matches = new ArrayList<>();
        for (Line line : lines) {
            String key = Person.key(line.name());
            Person match = people.findByNameOrAlias(sheetId, line.name()).orElse(null);
            matches.add(match);
            // A person named twice, by their name or an alias, is a repeat as much as a new name given twice.
            if (!names.add(match != null ? "#" + match.getId() : key)
                    || match == null && people.usedInTree(sheetId, key, null)) {
                throw new ImportPeopleException(line.number(), "the name " + line.name().trim() + " is already in use");
            }
            String contactKey = Person.contactKey(line.contact());
            if (contactKey != null && !contacts.add(contactKey)) {
                throw new ImportPeopleException(line.number(), "the contact " + contactKey + " is already in use");
            }
        }
        // Each person is checked again as the person form's are; a refused one rolls back those imported before it.
        int added = 0;
        int updated = 0;
        for (int i = 0; i < lines.size(); i++) {
            Line line = lines.get(i);
            Person match = matches.get(i);
            if (match == null) {
                people.add(sheetId, user, line.name(), line.grade(), line.terms(), line.contact());
                added++;
            } else {
                people.update(sheetId, user, match.getId(), null, match.getName(), line.grade(), null,
                        line.terms() != null ? line.terms() : match.getTerms(),
